catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    //Type appropriate comment here, and begin script below
    var gaMediaUtils = new GlideAjax("MediaUtilsClient");
    gaMediaUtils.addParam("sysparm_name", "getMediaData");
    gaMediaUtils.addParam("sysparm_media_sys_id", newValue);

    gaMediaUtils.getXMLAnswer(function(response) {
        var objResponse = JSON.parse(response);
        g_form.setValue("current_average_rating", objResponse.current_average_rating);
        g_form.setValue("current_synopsis", objResponse.current_synopsis);
        //g_form.setValue("poster_url", objResponse.poster_url);
		if(!objResponse.poster_url){
			g_form.setVisible("poster", false);
		}
		else{
			top.window.document.getElementById("poster_image").src = objResponse.poster_url;
			g_form.setVisible("poster", true);
		}
    });
}
